<script setup lang="ts">
useSeoPage('Create account', 'Create a 247URL account to manage links, QR codes, and analytics.', '/register')
const { register } = useAuth()
const form = reactive({ name: '', email: '', password: '', password_confirmation: '' })
const errors = ref<Record<string, string[]>>({}); const loading = ref(false)
async function submit() { loading.value = true; errors.value = {}; try { await register(form); await navigateTo('/dashboard') } catch (e: any) { errors.value = e?.data?.errors || { form: [e?.data?.message || 'Unable to create your account.'] } } finally { loading.value = false } }
</script>
<template><section class="container-shell py-16"><div class="mx-auto max-w-lg"><div class="surface p-7 sm:p-9"><p class="eyebrow">Start organizing</p><h1 class="mt-3 text-3xl font-black">Create your account</h1><p class="mt-3 text-slate-400">We’ll email you a verification link before link management is enabled.</p><form class="mt-7 grid gap-5" @submit.prevent="submit"><div><label class="label" for="name">Name</label><input id="name" v-model="form.name" class="input" autocomplete="name" required><p class="text-sm text-rose-300">{{ errors.name?.[0] }}</p></div><div><label class="label" for="email">Email</label><input id="email" v-model="form.email" class="input" type="email" autocomplete="email" required><p class="text-sm text-rose-300">{{ errors.email?.[0] }}</p></div><div class="grid gap-5 sm:grid-cols-2"><div><label class="label" for="password">Password</label><input id="password" v-model="form.password" class="input" type="password" autocomplete="new-password" required><p class="mt-1 text-xs text-slate-500">12+ characters with upper, lower, number, and symbol.</p></div><div><label class="label" for="password-confirmation">Confirm password</label><input id="password-confirmation" v-model="form.password_confirmation" class="input" type="password" autocomplete="new-password" required></div></div><p class="text-sm text-rose-300" role="alert">{{ errors.password?.[0] || errors.form?.[0] }}</p><button class="btn-primary w-full" :disabled="loading">{{ loading ? 'Creating account…' : 'Create account' }}</button></form><p class="mt-6 text-center text-sm text-slate-400">Already have an account? <NuxtLink to="/login" class="font-semibold text-teal-300">Sign in</NuxtLink></p></div></div></section></template>
